	var strScriptIncludeSysId = testdata.CreateScriptInclude(
		'global', 'Good1', 'function Test_Good1() {}', '', 'This is a test');
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strScriptIncludeSysId,false);

	var strScriptIncludeSysId = testdata.CreateScriptInclude(
		'global', 'Good2', 'function Test_Good2() { gs.addInfoMessage("INFO"); }', '', 'This is a test');
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strScriptIncludeSysId,false);
	
	var strScriptIncludeSysId = testdata.CreateScriptInclude(
		'global', 'Bad1', 'function Test_Bad1() { gs.addHighMessage("HIGH"); }', '', 'This is a test');
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strScriptIncludeSysId,true);
	
	var strScriptIncludeSysId = testdata.CreateScriptInclude(
		'global', 'Bad2', 'function Test_Bad2() { gs. addModerateMessage("MODERATE"); }', '', 'This is a test');
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strScriptIncludeSysId,true);

	var strScriptIncludeSysId = testdata.CreateScriptInclude(
		'global', 'Bad3', 'function Test_Bad3() { gs.addLowMessage ("LOW"); }', '', 'This is a test');
	test.TestCase_InstanceScanCheck(strCheck,'sys_script_include',strScriptIncludeSysId,true);

	var strScriptIncludeSysId = testdata.CreateScriptInclude(
